#include <chrono>
#include <iomanip>
#include <iostream>

#include <noarr/traversers.hpp>

// include common definitions (DATA_TYPE, SCALAR_VAL, EXP_FUN, POW_FUN, W, H, DEFINE_PROTO_STRUCT, ...)
#include "defines.hpp"

// include benchmark-specific definitions (problem sizes, etc.)
#include "deriche.hpp"

using num_t = DATA_TYPE;

namespace {

// convenient dimension proto-structures
constexpr auto i_vec = noarr::vector<'i'>();
constexpr auto j_vec = noarr::vector<'j'>();

// tuning of the logical layout (C-like: img[i][j], i = 0..W-1, j = 0..H-1)
struct tuning {
	// layout: scalar ^ vector<'j'> ^ vector<'i'>
	// -> second index ('j') is the innermost / contiguous dimension as in C
	DEFINE_PROTO_STRUCT(img_layout, j_vec ^ i_vec);
} tuning;

// -----------------------------------------------------------------------------
// Array initialization
// -----------------------------------------------------------------------------
void init_array(num_t &alpha, auto imgIn, auto imgOut) {
	using namespace noarr;

	// alpha parameter of the filter
	alpha = (num_t)0.25;

	// input should be between 0 and 1 (grayscale image pixel)
	traverser(imgIn).for_each([=](auto state) {
		auto [i, j] = get_indices<'i', 'j'>(state);
		imgIn[state] = (num_t)((313 * i + 991 * j) % 65536) / (num_t)65535.0;
	});

	// imgOut is not initialized in the original C code; left as-is
	(void)imgOut;
}

// -----------------------------------------------------------------------------
// Main computational kernel
// Original code provided by Gael Deest
// -----------------------------------------------------------------------------
[[gnu::flatten, gnu::noinline]]
void kernel_deriche(num_t alpha, auto imgIn, auto imgOut, auto y1, auto y2) {
	using namespace noarr;

	num_t xm1, tm1, ym1, ym2;
	num_t xp1, xp2;
	num_t tp1, tp2;
	num_t yp1, yp2;

	num_t k;
	num_t a1, a2, a3, a4, a5, a6, a7, a8;
	num_t b1, b2, c1, c2;

#pragma scop
	// -------------------------------------------------------------------------
	// Coefficient computation (same as in the C version)
	// -------------------------------------------------------------------------
	k = (SCALAR_VAL(1.0) - EXP_FUN(-alpha)) * (SCALAR_VAL(1.0) - EXP_FUN(-alpha))
	    / (SCALAR_VAL(1.0) + SCALAR_VAL(2.0) * alpha * EXP_FUN(-alpha)
	       - EXP_FUN(SCALAR_VAL(2.0) * alpha));
	a1 = a5 = k;
	a2 = a6 = k * EXP_FUN(-alpha) * (alpha - SCALAR_VAL(1.0));
	a3 = a7 = k * EXP_FUN(-alpha) * (alpha + SCALAR_VAL(1.0));
	a4 = a8 = -k * EXP_FUN(SCALAR_VAL(-2.0) * alpha);
	b1 = POW_FUN(SCALAR_VAL(2.0), -alpha);
	b2 = -EXP_FUN(SCALAR_VAL(-2.0) * alpha);
	c1 = c2 = SCALAR_VAL(1.0);

	// lengths in each dimension
	std::size_t width  = imgIn | get_length<'i'>(); // corresponds to _PB_W
	std::size_t height = imgIn | get_length<'j'>(); // corresponds to _PB_H

	// -------------------------------------------------------------------------
	// First pass: horizontal (along j), forward
	// for (i = 0; i < _PB_W; i++)
	//   { ym1 = ym2 = xm1 = 0;
	//     for (j = 0; j < _PB_H; j++)
	//       ...
	//   }
	// -------------------------------------------------------------------------
	traverser(y1, imgIn).template for_dims<'i'>([=](auto inner) {
		num_t local_ym1 = SCALAR_VAL(0.0);
		num_t local_ym2 = SCALAR_VAL(0.0);
		num_t local_xm1 = SCALAR_VAL(0.0);

		inner.template for_each<'j'>([=, &local_ym1, &local_ym2, &local_xm1](auto state) {
			// state contains fixed 'i' and varying 'j'
			y1[state] = a1 * imgIn[state] + a2 * local_xm1 + b1 * local_ym1 + b2 * local_ym2;
			local_xm1 = imgIn[state];
			local_ym2 = local_ym1;
			local_ym1 = y1[state];
		});
	});

	// -------------------------------------------------------------------------
	// Second pass: horizontal (along j), backward
	// for (i = 0; i < _PB_W; i++)
	//   { yp1 = yp2 = xp1 = xp2 = 0;
	//     for (j = _PB_H-1; j >= 0; j--)
	//       ...
	//   }
	//
	// We iterate 'j' forward with traverser, but reindex to j_rev = height-1-j
	// so that we access elements in the same order as the original backward loop.
	// -------------------------------------------------------------------------
	traverser(y2, imgIn).template for_dims<'i'>([=](auto inner) {
		num_t local_yp1 = SCALAR_VAL(0.0);
		num_t local_yp2 = SCALAR_VAL(0.0);
		num_t local_xp1 = SCALAR_VAL(0.0);
		num_t local_xp2 = SCALAR_VAL(0.0);

		inner.template for_each<'j'>([=, &local_yp1, &local_yp2, &local_xp1, &local_xp2](auto state) {
			auto [i_idx, j_idx] = get_indices<'i', 'j'>(state);
			std::size_t j_rev = height - 1 - j_idx;

			num_t &y2_ij  = y2.template at<'i', 'j'>(i_idx, j_rev);
			num_t img_val = imgIn.template at<'i', 'j'>(i_idx, j_rev);

			y2_ij = a3 * local_xp1 + a4 * local_xp2 + b1 * local_yp1 + b2 * local_yp2;
			local_xp2 = local_xp1;
			local_xp1 = img_val;
			local_yp2 = local_yp1;
			local_yp1 = y2_ij;
		});
	});

	// -------------------------------------------------------------------------
	// Combine horizontal passes:
	//   imgOut[i][j] = c1 * (y1[i][j] + y2[i][j]);
	// -------------------------------------------------------------------------
	traverser(imgOut, y1, y2).for_each([=](auto state) {
		imgOut[state] = c1 * (y1[state] + y2[state]);
	});

	// -------------------------------------------------------------------------
	// Third pass: vertical (along i), forward
	// for (j = 0; j < _PB_H; j++)
	//   { tm1 = ym1 = ym2 = 0;
	//     for (i = 0; i < _PB_W; i++)
	//       ...
	//   }
	// -------------------------------------------------------------------------
	traverser(y1, imgOut).template for_dims<'j'>([=](auto inner) {
		num_t local_tm1 = SCALAR_VAL(0.0);
		num_t local_ym1 = SCALAR_VAL(0.0);
		num_t local_ym2 = SCALAR_VAL(0.0);

		inner.template for_each<'i'>([=, &local_tm1, &local_ym1, &local_ym2](auto state) {
			y1[state] = a5 * imgOut[state] + a6 * local_tm1 + b1 * local_ym1 + b2 * local_ym2;
			local_tm1 = imgOut[state];
			local_ym2 = local_ym1;
			local_ym1 = y1[state];
		});
	});

	// -------------------------------------------------------------------------
	// Fourth pass: vertical (along i), backward
	// for (j = 0; j < _PB_H; j++)
	//   { tp1 = tp2 = yp1 = yp2 = 0;
	//     for (i = _PB_W-1; i >= 0; i--)
	//       ...
	//   }
	//
	// Again, we iterate 'i' forward with traverser, but reindex to
	//   i_rev = width-1-i
	// to mimic the backward traversal.
